import 'package:flutter/material.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:sehatak/core/services/pregnancy_service.dart';class PregnancyTrackerScreen extends StatefulWidget{const PregnancyTrackerScreen({super.key});@override State<PregnancyTrackerScreen>createState()=>_S();}class _S extends State<PregnancyTrackerScreen>{DateTime? due;int week=0;final weight=TextEditingController(),bp=TextEditingController(),notes=TextEditingController();bool saving=false;Future<void>pick()async{final d=await showDatePicker(context:context,firstDate:DateTime.now(),lastDate:DateTime.now().add(const Duration(days:280)),initialDate:due??DateTime.now().add(const Duration(days:210)));if(d!=null){week=await PregnancyService().calculateWeek(d);setState(()=>due=d);}}Future<void>save()async{final uid=FirebaseAuth.instance.currentUser?.uid;if(uid==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('سجل الدخول أولاً')));return;}setState(()=>saving=true);try{await PregnancyService().updateTracker(uid,{'dueDate':due,'currentWeek':week,'weight':double.tryParse(weight.text),'bp':bp.text.trim(),'notes':notes.text.trim()});if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم حفظ متابعة الحمل')));}finally{if(mounted)setState(()=>saving=false);}}@override void dispose(){weight.dispose();bp.dispose();notes.dispose();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('أداة متابعة الحمل')),body:ListView(padding:const EdgeInsets.all(20),children:[Card(child:ListTile(leading:const Icon(Icons.calendar_today,color:Color(0xFFE91E63)),title:Text(due==null?'اختر تاريخ الولادة المتوقع':'الولادة المتوقعة: ${due!.day}/${due!.month}/${due!.year}'),subtitle:Text('الأسبوع الحالي: $week / 40'),onTap:pick)),const SizedBox(height:12),TextField(controller:weight,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'الوزن (كجم)',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:bp,decoration:const InputDecoration(labelText:'ضغط الدم',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:notes,maxLines:4,decoration:const InputDecoration(labelText:'ملاحظات',border:OutlineInputBorder())),const SizedBox(height:18),ElevatedButton(onPressed:saving?null:save,child:Text(saving?'جارٍ الحفظ...':'حفظ بيانات الحمل')),const SizedBox(height:18),const Text('التذكيرات الطبية',style:TextStyle(fontWeight:FontWeight.w800,fontSize:17)),const Text('8–12 أسبوع: التحاليل الأولى\n18–22 أسبوع: السونار التفصيلي\n24–28 أسبوع: فحص السكري\n36+ أسبوع: الاستعداد للولادة') ]));}}
